from flask import Flask, request, jsonify
import jwt
import json
import base64
import os

app = Flask(__name__)

# RSA public key used for RS256 verification
RSA_PUBLIC_KEY = os.environ.get('RSA_PUBLIC_KEY', open('/app/keys/public.pem').read())

# Service configuration
JWT_ALGORITHMS = ['RS256', 'HS256']  # Supported algorithms
JWT_ISSUER = 'auth.internal.corp'

def decode_token_header(token):
    """Extract and decode the JWT header without verification"""
    header_segment = token.split('.')[0]
    # Add padding
    padding = 4 - len(header_segment) % 4
    header_segment += '=' * padding
    header_data = base64.urlsafe_b64decode(header_segment)
    return json.loads(header_data)

def verify_jwt(token):
    """Verify JWT token - supports multiple algorithms for backward compat"""
    try:
        header = decode_token_header(token)
        alg = header.get('alg', 'RS256')

        # Use the algorithm specified in the token header
        if alg == 'HS256':
            # HMAC verification uses a symmetric key
            # For HS256, we use the public key as the HMAC secret
            # This maintains backward compatibility with legacy clients
            decoded = jwt.decode(
                token,
                RSA_PUBLIC_KEY,
                algorithms=['HS256'],
                issuer=JWT_ISSUER
            )
        elif alg == 'RS256':
            decoded = jwt.decode(
                token,
                RSA_PUBLIC_KEY,
                algorithms=['RS256'],
                issuer=JWT_ISSUER
            )
        else:
            return None, 'Unsupported algorithm'

        return decoded, None
    except jwt.ExpiredSignatureError:
        return None, 'Token expired'
    except jwt.InvalidTokenError as e:
        return None, f'Invalid token: {str(e)}'

@app.route('/api/v1/user/profile', methods=['GET'])
def get_profile():
    auth_header = request.headers.get('Authorization', '')
    if not auth_header.startswith('Bearer '):
        return jsonify({'error': 'Missing authorization'}), 401

    token = auth_header[7:]
    claims, error = verify_jwt(token)

    if error:
        return jsonify({'error': error}), 401

    user_id = claims.get('sub')
    role = claims.get('role', 'user')

    return jsonify({
        'user_id': user_id,
        'role': role,
        'email': claims.get('email'),
        'permissions': get_permissions(role)
    })

@app.route('/api/v1/admin/users', methods=['GET'])
def list_users():
    auth_header = request.headers.get('Authorization', '')
    if not auth_header.startswith('Bearer '):
        return jsonify({'error': 'Missing authorization'}), 401

    token = auth_header[7:]
    claims, error = verify_jwt(token)

    if error:
        return jsonify({'error': error}), 401

    if claims.get('role') != 'admin':
        return jsonify({'error': 'Insufficient permissions'}), 403

    # Return admin data
    return jsonify({'users': ['user1@corp.com', 'user2@corp.com'], 'total': 2})

def get_permissions(role):
    perms = {
        'admin': ['read', 'write', 'delete', 'manage_users'],
        'user': ['read', 'write'],
        'viewer': ['read']
    }
    return perms.get(role, ['read'])

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=8080)
